// Чистая Code-нода: валидация, отсечение мусора и сборка атомарного REST-пакета WP
const item = $input.first().json;

// 1. Быстрый сброс тяжелых/бинарных полей из входного потока
const { raw_html, raw_markdown_debug, trace_logs, ...cleanPayload } = item;

// 2. Валидация обязательного контракта статьи
if (!cleanPayload.title || !cleanPayload.content || !cleanPayload.solder_alloy) {
  throw new Error('Contract Violation: title, content or solder_alloy is missing');
}

// 3. Формирование атомарного полезного груза для WordPress REST API
// WP принимает пост, мета-поля и таксономию в ОДНОМ HTTP-запросе
const wpPostPayload = {
  title: cleanPayload.title,
  content: cleanPayload.content,
  status: cleanPayload.publish_now ? 'publish' : 'draft',
  slug: cleanPayload.slug || '',
  meta: {
    tchp_solder_alloy: cleanPayload.solder_alloy,
    tchp_temperature: cleanPayload.temperature || '',
    tchp_difficulty: cleanPayload.difficulty || 'Мастер',
    tchp_time_required: cleanPayload.time_required || '15 мин',
    tchp_flux_recommended: cleanPayload.flux_recommended || '',
    tchp_tip_geometry: cleanPayload.tip_geometry || '',
    tchp_faq_items: cleanPayload.faq_items || [],
    tchp_sources: cleanPayload.sources || []
  }
};

return [{ json: wpPostPayload }];
